rules.logic:
if (element.querySelector('.custom-directory-grid')) return;

var grid = document.createElement('div');
grid.className = 'custom-directory-grid';
grid.style.cssText = 'max-width:900px;margin:40px auto;padding:20px;';

var title = document.createElement('h1');
title.textContent = 'Choose a Category';
title.style.cssText = 'font-size:2rem;font-weight:700;text-align:center;margin-bottom:32px;color:#1d1d1f;';
grid.appendChild(title);

var gridContainer = document.createElement('div');
gridContainer.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;';

var categories = [
  { name: 'News', url: 'https://www.yahoo.com/news/', icon: '📰', color: '#7c3aed' },
  { name: 'Finance', url: 'https://finance.yahoo.com/', icon: '📈', color: '#059669' },
  { name: 'Sports', url: 'https://sports.yahoo.com/', icon: '⚽', color: '#dc2626' },
  { name: 'Weather', url: 'https://weather.yahoo.com/', icon: '🌤️', color: '#0ea5e9' },
  { name: 'Entertainment', url: 'https://www.yahoo.com/entertainment/', icon: '🎬', color: '#db2777' },
  { name: 'Technology', url: 'https://tech.yahoo.com/', icon: '💻', color: '#6366f1' },
  { name: 'Health', url: 'https://health.yahoo.com/', icon: '❤️', color: '#ef4444' },
  { name: 'Lifestyle', url: 'https://www.yahoo.com/lifestyle/', icon: '🌿', color: '#16a34a' },
  { name: 'Shopping', url: 'https://shopping.yahoo.com/', icon: '🛒', color: '#f59e0b' },
  { name: 'Games', url: 'https://www.yahoo.com/games/', icon: '🎮', color: '#8b5cf6' },
  { name: 'Search', url: 'https://search.yahoo.com/', icon: '🔍', color: '#0891b2' },
  { name: 'Mail', url: 'https://mail.yahoo.com/', icon: '✉️', color: '#a855f7' }
];

categories.forEach(function(cat) {
  var btn = document.createElement('a');
  btn.href = cat.url;
  btn.target = '_blank';
  btn.rel = 'noopener noreferrer';
  btn.style.cssText = 'display:flex;flex-direction:column;align-items:center;justify-content:center;padding:32px 16px;border-radius:16px;text-decoration:none;font-weight:600;font-size:1.1rem;color:#fff;background:' + cat.color + ';transition:transform 0.15s ease,box-shadow 0.15s ease;box-shadow:0 2px 8px rgba(0,0,0,0.15);cursor:pointer;';

  var icon = document.createElement('div');
  icon.textContent = cat.icon;
  icon.style.cssText = 'font-size:2.5rem;margin-bottom:12px;';

  var label = document.createElement('span');
  label.textContent = cat.name;

  btn.appendChild(icon);
  btn.appendChild(label);

  btn.addEventListener('mouseenter', function() {
    btn.style.transform = 'translateY(-4px)';
    btn.style.boxShadow = '0 6px 16px rgba(0,0,0,0.25)';
  });
  btn.addEventListener('mouseleave', function() {
    btn.style.transform = 'translateY(0)';
    btn.style.boxShadow = '0 2px 8px rgba(0,0,0,0.15)';
  });

  gridContainer.appendChild(btn);
});

grid.appendChild(gridContainer);
element.innerHTML = '';
element.style.display = 'block';
element.appendChild(grid);
